const $=id=>document.getElementById(id);const KEY='otoko-talk-retro-v18';let seen=[];try{seen=JSON.parse(localStorage.getItem(KEY)||'[]')}catch{}let batch=[];let active=null;let hiddenNo=0;const CATS=['すべて','麻雀','ニュース','平成・思い出','究極の選択','恋愛・人生','ちょいエロ','男4人の本音','4人の新企画','もし◯◯なら誰？','大人の本音'];const names=['たけ','かず','たろう','つよし'];function allowed(){let cat=$('category').value;return DATA.filter(t=>(cat==='すべて'||t.cat===cat))}function save(){try{localStorage.setItem(KEY,JSON.stringify(seen.slice(-400)))}catch{}}function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function newBatch(){let pool=allowed().filter(t=>!seen.includes(t.id));if(pool.length<8){seen=seen.filter(id=>!allowed().some(t=>t.id===id));pool=allowed()}batch=shuffle([...pool]).slice(0,8).map(t=>({...t,used:false}));render();save()}// Manually proofread breaks for all 80 topics. Pipe is a possible wrap point,
